Защита веб-сервера: rate limiting и защита от брутфорса

👋 Приветствую в мире цифровой безопасности!

Расскажу про ограничение запросов в Nginx - как не дать ботам и сканерам положить сервис или перебрать пароли.

⏺Базовый rate limiting через limit_req - зона в памяти с ключом по IP и лимитом запросов в секунду:

http {
    limit_req_zone $binary_remote_addr zone=general:10m rate=10r/s;
    limit_req_zone $binary_remote_addr zone=login:10m rate=1r/s;
    limit_conn_zone $binary_remote_addr zone=conn_limit:10m;
}

server {
    location / {
        limit_req zone=general burst=20 nodelay;
        limit_conn conn_limit 10;
    }

    location /login {
        limit_req zone=login burst=5;
        limit_req_status 429;
    }
}

burst=20 разрешает краткосрочный всплеск до 20 запросов, nodelay обрабатывает их немедленно без очереди. Без nodelay запросы из burst-буфера обрабатываются с задержкой, что создаёт очередь и замедляет легитимных пользователей.

⏺Разные зоны для разных эндпоинтов - API и страница логина должны иметь разные лимиты:

limit_req_zone $binary_remote_addr zone=api:10m rate=30r/s;
limit_req_zone $binary_remote_addr zone=auth:10m rate=1r/m;
limit_req_zone $binary_remote_addr zone=static:10m rate=100r/s;

location /api/ {
    limit_req zone=api burst=50 nodelay;
}

location ~* \.(js|css|png|jpg|gif|ico|woff)$ {
    limit_req zone=static burst=200 nodelay;
}

location ~ ^/(login|signup|reset-password) {
    limit_req zone=auth burst=3;
    limit_req_status 429;
}

⏺Блокируем подозрительные User-Agent и пустые запросы - большинство простых ботов не заморачиваются с заголовками:

map $http_user_agent $bad_bot {
    default 0;
    ~*masscan 1;
    ~*zgrab 1;
    ~*nikto 1;
    ~*sqlmap 1;
    "" 1;
}

server {
    if ($bad_bot) {
        return 444;
    }
}

444 это специальный код Nginx - закрывает соединение без отправки ответа, бот не получает даже подтверждения, что сервер существует.

⏺Geo-блокировка через встроенный модуль, если трафик из конкретных стран явно нелегитимен:

geoip2 /etc/nginx/GeoLite2-Country.mmdb {
    $geoip2_data_country_code country iso_code;
}

map $geoip2_data_country_code $allowed {
    default 0;
    RU 1;
    BY 1;
    KZ 1;
}

server {
    if ($allowed = 0) {
        return 403;
    }
}

⏺Логируем заблокированные запросы отдельно для анализа:

log_format blocked '$remote_addr - $time_local "$request" '
                   '$status "$http_user_agent" "$http_referer"';

access_log /var/log/nginx/blocked.log blocked if=$bad_bot;

Отдельный лог даёт чистую картину атак без смешивания с легитимным трафиком.

